```javascript
import { MeshStandardNodeMaterial, BoxGeometry, DirectionalLight } from 'three/webgpu';
import { uv, mix, uniform } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new THREE.Group();

  // Color definitions
  const colors = {
    gradTop: new THREE.Color('#1a1a22'),
    gradBottom: new THREE.Color('#121218'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38'),
  };

  // Brand names (6 tiles, 3x2 grid)
  const brands = [
    'HODINKEE',
    'MONOCLE',
    'WALLPAPER',
    'ESQUIRE',
    'WIRED',
    'FINANCIAL TIMES',
  ];

  // Grid constants
  const TILE_WIDTH = 1.0;
  const TILE_HEIGHT = 0.62;
  const TILE_GAP = 0.25;
  const GRID_WIDTH = 3.5;
  const GRID_HEIGHT = 1.49;

  // Kicker text positioned above grid
  const kicker = ctx.fontAtlas.createText('AS FEATURED IN', {
    fontSize: 9,
    color: colors.paper,
    align: 'center',
  });
  kicker.position.y = GRID_HEIGHT / 2 + 0.3;
  root.add(kicker);

  // Material factory with vertical gradient albedo
  const createTileMaterial = () => {
    const mat = new MeshStandardNodeMaterial({
      colorNode: mix(
        uniform(colors.gradTop),
        uniform(colors.gradBottom),
        uv().y
      ),
      metalness: 0.5,
      roughness: 0.55,
      clearcoat: 0.2,
    });
    mat.anisotropy = 0.6;
    return mat;
  };

  // Shared tile geometry
  const tileGeometry = new THREE.BoxGeometry(
    TILE_WIDTH,
    TILE_HEIGHT,
    0.05,
    8,
    8,
    2
  );

  // Build tile grid
  const tiles = [];

  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 3; col++) {
      // Tile position
      const x =
        -GRID_WIDTH / 2 +
        col * (TILE_WIDTH + TILE_GAP) +
        TILE_WIDTH / 2;
      const y =
        GRID_HEIGHT / 2 -
        row * (TILE_HEIGHT + TILE_GAP) -
        TILE_HEIGHT / 2;

      // Tile group (for animations)
      const tileGroup = new THREE.Group();
      tileGroup.position.set(x, y, 0);

      // Tile mesh
      const mesh = new THREE.Mesh(tileGeometry, createTileMaterial());
      tileGroup.add(mesh);

      // Brand text on tile
      const brandIndex = row * 3 + col;
      const brandText = ctx.fontAtlas.createText(brands[brandIndex], {
        fontSize: 13,
        color: colors.paper,
        align: 'center',
      });
      brandText.position.z = 0.05;

      if (brandText.material) {
        brandText.material.transparent = true;
        brandText.material.opacity = 0.78;
      }

      tileGroup.add(brandText);
      root.add(tileGroup);

      tiles.push({
        group: tileGroup,
        mesh,
        text: brandText,
        row,
        col,
        startY: y,
      });
    }
  }

  // Key light at 35° elevation (for anisotropic highlight rake)
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  const elevation = (35 * Math.PI) / 180;
  keyLight.position.set(
    Math.cos(elevation) * 3,
    Math.sin(elevation) * 3,
    1
  );
  root.add(keyLight);

  // Rim light with accent color
  const rimLight = new THREE.DirectionalLight(colors.accent, 0.8);
  rimLight.position.set(-2, -1, 2);
  root.add(rimLight);

  // Mount animation: stagger fade-up
  tiles.forEach(({ group, text, row, col, startY }) => {
    const staggerIndex = row * 3 + col;
    const delay = staggerIndex * 0.08;

    // Slide up
    gsap.fromTo(
      group.position,
      { y: startY + 0.2 },
      {
        y: startY,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        delay,
      }
    );

    // Fade in text
    if (text.material) {
      gsap.fromTo(
        text.material,
        { opacity: 0 },
        {
          opacity: 0.78,
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
          delay,
        }
      );
    }
  });

  // Hover interaction handlers
  tiles.forEach(({ group, text }) => {
    group.userData.handlers = {
      hover: (state) => {
        const targetOpacity = state.isHovering ? 1.0 : 0.78;
        const targetZ = state.isHovering ? 0.05 : 0;

        if (text.material) {
          gsap.to(text.material, {
            opacity: targetOpacity,
            duration: 0.16,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
          });
        }

        gsap.to(group.position, {
          z: targetZ,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
      },
    };
  });

  // Cleanup
  root.userData.cleanup = () => {
    // Kill all animations
    tiles.forEach(({ group, text }) => {
      gsap.killTweensOf(group.position);
      if (text.material) {
        gsap.killTweensOf(text.material);
      }
    });

    // Dispose resources
    tiles.forEach(({ mesh }) => {
      mesh.geometry.dispose();
      mesh.material.dispose();
    });
    tileGeometry.dispose();
  };

  return root;
}
